def run(cmd, check=True, **kwargs):
    print(f"$ {cmd}")
    return subprocess.run(cmd, shell=True, check=check, **kwargs)


def node_is_new_enough():
    try:
        out = subprocess.run(["node", "-v"], capture_output=True, text=True, check=True).stdout.strip()
    except Exception:
        return False, None
    major, minor = (int(part) for part in out.lstrip("v").split(".")[:2])
    return (major > 22 or (major == 22 and minor >= 19)), out


def ensure_node():
    ok, version = node_is_new_enough()
    if ok:
        print(f"Node.js {version} 已满足要求")
        return
    print(f"当前 Node.js {version} 太老，安装 {NODE_VERSION}")
    arch = "x64" if os.uname().machine in ("x86_64", "amd64") else "arm64"
    tarball = f"node-{NODE_VERSION}-linux-{arch}.tar.xz"
    run(f"curl -fsSL https://nodejs.org/dist/{NODE_VERSION}/{tarball} -o /tmp/{tarball}")
    run(f"tar -xJf /tmp/{tarball} -C /usr/local --strip-components=1 --exclude=CHANGELOG.md")
    os.environ["PATH"] = f"/usr/local/bin:{os.environ.get('PATH', '')}"
    ok, version = node_is_new_enough()
    if not ok:
        raise SystemExit(f"Node.js 安装失败，当前版本 {version}")


def ensure_pnpm():
    if shutil.which("pnpm"):
        print("pnpm 已安装")
        return
    run("corepack enable || true", check=False)
    if not shutil.which("pnpm"):
        run("npm install -g pnpm@11.28.5")


def write_patch():
    """把生成这份脚本时用到的补丁原样写到磁盘上。"""
    with open(PATCH_PATH, "wb") as handle:
        handle.write(base64.b64decode("".join(PATCH_B64_CHUNKS)))
    print(f"补丁已写出: {PATCH_PATH} ({os.path.getsize(PATCH_PATH)} 字节)")


def sync_repo():
    if not os.path.isdir(os.path.join(DSH_SRC, ".git")):
        run(f"git clone --filter=blob:none {REPO_URL} {DSH_SRC}", check=False)
        if not os.path.isdir(os.path.join(DSH_SRC, ".git")):
            run(f"git clone {REPO_URL} {DSH_SRC}")
    os.chdir(DSH_SRC)
    run("git fetch --tags origin || true", check=False)
    probe = subprocess.run(f"git cat-file -e {PINNED_COMMIT}^{{commit}}", shell=True)
    if probe.returncode == 0:
        run(f"git checkout --detach {PINNED_COMMIT}")
    else:
        print(f"!! 本地没有提交 {PINNED_COMMIT}，停在当前分支，用 3-way 打补丁")


def apply_patch():
    already = subprocess.run(f"git apply --reverse --check {PATCH_PATH}", shell=True,
                             capture_output=True, text=True)
    if already.returncode == 0:
        print("补丁已经打过，跳过")
        return
    direct = subprocess.run(f"git apply --check {PATCH_PATH}", shell=True, capture_output=True, text=True)
    if direct.returncode == 0:
        run(f"git apply {PATCH_PATH}")
        print("补丁应用成功")
        return
    print("直接应用失败，尝试 3-way：")
    run(f"git apply --3way {PATCH_PATH}")


def build():
    run("pnpm install")
    run("pnpm run build")
    index = os.path.join(DSH_SRC, "apps", "web", "dist", "index.html")
    if not os.path.isfile(index):
        raise SystemExit("构建结束但没有 apps/web/dist/index.html，构建失败")
    print("构建完成 ✅")


os.makedirs(os.path.dirname(DSH_SRC) or ".", exist_ok=True)

write_patch()
ensure_node()
ensure_pnpm()
sync_repo()
apply_patch()
build()


# @title 2. 🔐 设置访问密码 {"single-column":true}
# @markdown 这个密码就是 `dsh web -pwd <password>` 里的那个参数。
# @markdown 网页第一次打开会让你输入它；**第一个输对的来源 IP 会被记住**，之后只有这个 IP 能用。
dsh_password = "change-me-please"  # @param {type:"string"}
port = 3080  # @param {type:"integer"}
use_cloudflare = True  # @param {type:"boolean"}
open_browser = False  # @param {type:"boolean"}
# @markdown 把它设成 False 就只做前面两步（装环境/构建/打补丁），不启动服务也不开隧道。
launch_now = True  # @param {type:"boolean"}


# @title 3. 🚀 启动 dsh web（可选 Cloudflare 临时隧道） {"single-column":true}
import socket
import threading
import time


def cloudflared_asset():
    """按当前平台挑 cloudflared 的下载包。"""
    system, machine = os.uname().sysname, os.uname().machine
    arch = "amd64" if machine in ("x86_64", "amd64") else "arm64"
    if system == "Linux":
        return f"cloudflared-linux-{arch}", False
    if system == "Darwin":
        return f"cloudflared-darwin-{arch}.tgz", True
    raise SystemExit(f"不认识的平台 {system}-{machine}，请先自行安装 cloudflared")


def ensure_cloudflared():
    """找到或下载 cloudflared；装到用户目录，不需要 root。"""
    found = shutil.which("cloudflared")
    if found:
        print(f"cloudflared 已安装: {found}")
        return found
    target = os.path.expanduser("~/.local/bin/cloudflared")
    if os.path.exists(target):
        return target
    asset, is_tarball = cloudflared_asset()
    print(f"安装 cloudflared ({asset}) ...")
    os.makedirs(os.path.dirname(target), exist_ok=True)
    url = f"https://github.com/cloudflare/cloudflared/releases/latest/download/{asset}"
    if is_tarball:
        run(f'curl -fsSL {url} -o "{target}.tgz" && tar -xzf "{target}.tgz" -C "{os.path.dirname(target)}" cloudflared && rm -f "{target}.tgz"')
    else:
        run(f'curl -fsSL {url} -o "{target}"')
    run(f'chmod +x "{target}"')
    return target


def wait_for_port(host, target_port, timeout=600):
    """等 harness 真正开始监听端口。"""
    deadline = time.time() + timeout
    while time.time() < deadline:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
            sock.settimeout(0.5)
            if sock.connect_ex((host, target_port)) == 0:
                return True
        time.sleep(0.5)
    return False


def start_tunnel(target_port):
    """先起隧道，拿到 trycloudflare 域名（后面要把它加进 --trusted-host）。"""
    binary = ensure_cloudflared()
    print("启动 Cloudflare 临时隧道 ...")
    process = subprocess.Popen(
        [binary, "tunnel", "--url", f"http://127.0.0.1:{target_port}", "--no-autoupdate"],
        stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1,
    )
    public_url = None
    deadline = time.time() + 120
    while time.time() < deadline:
        line = process.stdout.readline()
        if not line:
            if process.poll() is not None:
                raise SystemExit("cloudflared 提前退出")
            time.sleep(0.2)
            continue
        match = re.search(r"https://[a-z0-9-]+\.trycloudflare\.com", line)
        if match:
            public_url = match.group(0)
            break
    if public_url is None:
        raise SystemExit("120 秒内没拿到 trycloudflare 地址")
    # 继续把 cloudflared 的日志丢掉，避免管道写满把它卡死。
    threading.Thread(target=lambda: [None for _ in process.stdout], daemon=True).start()
    return process, public_url


tunnel_process = None
public_url = None
if not launch_now:
    print("launch_now=False：环境/构建/补丁已经准备好，服务没有启动。")
    print(f"想启动时把 launch_now 改成 True，或手动执行：")
    print(f"  cd {DSH_SRC}")
    print(f"  node --import tsx/esm apps/cli/src/bin.ts web -pwd {dsh_password!r} --no-open --port {port}")
    raise SystemExit(0)

if use_cloudflare:
    tunnel_process, public_url = start_tunnel(port)

dsh_args = [
    "node", "--import", "tsx/esm", "apps/cli/src/bin.ts",
    "web",
    "-pwd", dsh_password,
    "--host", "127.0.0.1",
    "--port", str(port),
]
if not open_browser:
    dsh_args.append("--no-open")
if public_url is not None:
    tunnel_host = public_url[len("https://"):].split("/")[0]
    # cloudflared 会把公网域名放进 Host 头，harness 的 /api 主机栅栏只接受
    # loopback、监听地址和 --trusted-host 列出的 authority，所以要显式放行。
    dsh_args += ["--trusted-host", tunnel_host, "--public-url", public_url + "/"]

print("=" * 60)
print(f"  本地地址 : http://127.0.0.1:{port}")
if public_url:
    print(f"  公网地址 : {public_url}/")
    print("             ↑ 用浏览器打开这个地址")
print(f"  登录密码 : {dsh_password}")
print("  IP 绑定  : 第一个输对密码的来源 IP 会被记住，之后只有它能访问")
print("=" * 60)
print()

os.chdir(DSH_SRC)
process = subprocess.Popen(dsh_args, cwd=DSH_SRC)
print(f"$ {' '.join(dsh_args)}")

# 等端口起来后再把结论打印一次，方便挂机时看结果。
if wait_for_port("127.0.0.1", port):
    print(f"\nharness 已经在 http://127.0.0.1:{port} 上监听")
    if public_url:
        print(f"公网地址: {public_url}/\n把密码 {dsh_password!r} 输进网页即可（只有你这台设备的 IP 能用）")
else:
    print("\n10 分钟内没等到端口打开，检查上面的日志")

# 让 dsh web 一直跑着，Ctrl-C / 停掉单元格就结束。
try:
    process.wait()
except KeyboardInterrupt:
    process.terminate()
finally:
    if tunnel_process is not None:
        tunnel_process.terminate()
